const slug=(x:string)=>x.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
export function initialToolFamilies():ToolFamily[]{
 const seen=new Set<string>();
 return source.trim().split('\n').map(line=>{
  const [type,discipline,category,family,attributeText,itemText]=line.split('|');
  const kind=type==='T'?'Tools':'Equipment';
  const code=[type.toLowerCase(),discipline,category,family].map(slug).join('-');
  const attributes=attributeText.split(';').map(label=>({key:slug(label),label}));
  const items=itemText.split(';').filter(name=>{const k=slug(name);if(seen.has(k))return false;seen.add(k);return true;}).map(name=>({code:code+'--'+slug(name),name}));
  return {code,kind,discipline,category,family,attributes,items};
 }).filter(f=>f.items.length) as ToolFamily[];
}
export function expandToolFamily(f:ToolFamily):ToolCatalogueItem[]{return f.items.map(i=>({...i,kind:f.kind,discipline:f.discipline,category:f.category,family:f.family,familyCode:f.code,attributes:f.attributes}));}
